  function beginStageVictory(){state.mode='victory';state.bossPhase='cleared';stopHum();asteroids.length=orbs.length=scraps.length=powerups.length=plasma.length=lasers.length=0;let ready=0;hydroBeds=hydroBeds.map(b=>{if(!b)return b;if(!b.hydrated&&!baseSystems.hydroBot)return b;const gain=baseSystems.powerTier>=3?3:baseSystems.powerTier===2?1.5:1,grown={...b,progress:Math.min(3,(b.progress??b.stage??0)+gain),hydrated:false};grown.stage=Math.floor(grown.progress);if(grown.stage>=3)ready++;return grown;});pendingAutomation=true;baseSystems.merchantDocked=Math.random()<.38;saveFarm();ui.bossStatus.classList.remove('active');ui.bossWarning.classList.remove('active');ui.touchHint.style.opacity='0';unlockedLevel=Math.max(unlockedLevel,state.level+1);localStorage.setItem('unlocked_level',String(unlockedLevel));ui.victoryLevel.textContent=String(state.level);ui.victoryDistance.textContent=fmt(state.score);ui.victoryScrap.textContent=`✦ ${fmtScrap(Math.max(0,profile.scrap-state.runStartScrap))}`;ui.victoryBosses.textContent=`${state.bossesDefeated} / ${state.requiredBosses}`;document.querySelector('.victory-copy').textContent=ready?`${ready} HYDRO-CROP${ready===1?'':'S'} READY TO HARVEST AT MOTHER BASE`:'DREADNOUGHT FORMATION ELIMINATED · CROPS ADVANCED 1 STAGE';shell.classList.remove('anomaly-warning');shell.classList.add('stage-victory');state.warpTimer=2;state.shake=34;tone(120,1700,1.65,.075,'sawtooth');victoryTimeout=setTimeout(()=>{shell.classList.remove('stage-victory');ui.victoryScreen.classList.add('active');pickupChime(true);},2000);}
