  function fireLaser(){if(state.mode!=='playing'||state.fireCooldown>0)return;const level=profile.upgrades.laser,cooldowns=[.2,.17,.14,.11],boltWidth=4+level*1.7+(state.activeBuffs.targeting?2.5:0),shots=state.spreadTimer>0?[-.22,0,.22]:[0],racks=hasPart('cannons')?[-7,7]:[0],damage=(hasPart('cannons')?2:1)*(state.activeBuffs.explosive?2:1)*(1+profile.upgrades.overcharge*.15);state.fireCooldown=cooldowns[level]*(hasPart('cannons')?.8:1)*(1-profile.upgrades.thermal*.12);for(const angle of shots)for(const offset of racks)lasers.push({x:player.x+offset,y:player.y-player.h*.52,w:boltWidth,h:30+level*6,speed:860,vx:Math.sin(angle)*860,vy:-Math.cos(angle)*860,damage});if(state.droneTimer>0)for(const offset of [-34,34])lasers.push({x:player.x+offset,y:player.y-8,w:Math.max(3,boltWidth-1),h:24+level*4,speed:860,vx:0,vy:-860,drone:true,damage:1});for(let i=0;i<8;i++)particles.push({x:player.x+(Math.random()-.5)*7,y:player.y-player.h*.49,vx:(Math.random()-.5)*90,vy:-80-Math.random()*180,life:.08+Math.random()*.12,max:.2,color:'#b9ffff',size:1+Math.random()*2,pixel:true});tone(980,540,.09,.035,'square');}
