    for(let i=asteroids.length-1;i>=0;i--){const a=asteroids[i];a.y+=a.speed*state.speed*dt;a.x+=(a.vx||0)*dt;a.rot+=a.spin*dt;a.flash=Math.max(0,a.flash-dt);if(a.y>height+a.r||a.x<-120||a.x>width+120){asteroids.splice(i,1);continue;}if(circleHit(player,a,player.w*.46,a.r*.82)){asteroids.splice(i,1);burst(a.x,a.y,'#ff476b',35,250);if(damagePlayer(34))return;}}if(state.boss)state.boss.hitFlash=Math.max(0,state.boss.hitFlash-dt);for(let i=enemies.length-1;i>=0;i--){const e=enemies[i];e.t+=dt;e.y+=e.speed*dt;e.x=e.baseX+Math.sin(e.t*1.6)*70;e.flash=Math.max(0,e.flash-dt);e.fireCd-=dt;if(e.y>height+40){enemies.splice(i,1);continue;}if(e.fireCd<=0&&e.y>10&&e.y<height*.82){e.fireCd=1.4+Math.random()*1.1;const tx=player.x-e.x,ty=player.y-e.y,d=Math.hypot(tx,ty)||1;enemyBolts.push({x:e.x,y:e.y+14,vx:tx/d*260,vy:Math.max(140,ty/d*260),r:5});tone(300,140,.14,.05,'square');}if(circleHit(player,e,player.w*.46,e.r*.85)){enemies.splice(i,1);burst(e.x,e.y,'#ff8a3d',30,220);if(damagePlayer(30))return;}}for(let i=enemyBolts.length-1;i>=0;i--){const b=enemyBolts[i];b.x+=b.vx*dt;b.y+=b.vy*dt;if(b.y>height+30||b.x<-40||b.x>width+40){enemyBolts.splice(i,1);continue;}if(circleHit(player,b,player.w*.4,b.r+3)){enemyBolts.splice(i,1);burst(b.x,b.y,'#ff5d7a',14,140);if(damagePlayer(14))return;}}
