  function drawPlasma(p){ctx.save();ctx.translate(p.x,p.y);ctx.shadowBlur=20+Math.sin(p.pulse)*4;ctx.shadowColor='#ff143f';ctx.fillStyle='#ff315d';ctx.strokeStyle='#fff0f3';ctx.lineWidth=1.2;ctx.beginPath();ctx.arc(0,0,p.r,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.restore();}
  function drawLaser(l){ctx.save();ctx.shadowBlur=15;ctx.shadowColor='#65f4ff';const g=ctx.createLinearGradient(l.x,l.y+l.h,l.x,l.y-l.h*.5);g.addColorStop(0,'transparent');g.addColorStop(.35,'#3bdfff');g.addColorStop(1,'#efffff');ctx.fillStyle=g;ctx.fillRect(l.x-l.w/2,l.y-l.h,l.w,l.h*1.5);ctx.restore();}
