  function drawScrap(s){ctx.save();ctx.translate(s.x,s.y);ctx.rotate(s.rot);ctx.shadowBlur=18;ctx.shadowColor='#ffd84d';ctx.fillStyle='#fff09a';ctx.strokeStyle='#ffcf38';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(0,-s.r);ctx.lineTo(s.r*.55,-s.r*.35);ctx.lineTo(s.r,0);ctx.lineTo(s.r*.35,s.r*.55);ctx.lineTo(0,s.r);ctx.lineTo(-s.r*.55,s.r*.35);ctx.lineTo(-s.r,0);ctx.lineTo(-s.r*.35,-s.r*.55);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#8f5c08';ctx.fillRect(-2,-2,4,4);ctx.restore();}
  function drawPowerup(p){ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.rot);ctx.shadowBlur=22+Math.sin(p.pulse)*5;ctx.shadowColor='#ffe66d';ctx.fillStyle='#160f03';ctx.strokeStyle='#ffe66d';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,p.r,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.rotate(-p.rot);ctx.fillStyle='#fff4a3';ctx.font='700 15px Orbitron, sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(p.type,0,1);ctx.restore();}
