  function drawBase(){ctx.fillStyle='#000';ctx.fillRect(0,0,width,height);const mx=Math.max(22,width*.055),my=Math.max(76,height*.1),w=width-mx*2,h=height-my*1.65,x=v=>mx+v*w,y=v=>my+v*h;ctx.save();ctx.lineWidth=1;ctx.strokeStyle='#173e4b';ctx.shadowBlur=8;ctx.shadowColor='#65f4ff';for(let i=0;i<=12;i++){ctx.globalAlpha=i%3===0?.34:.12;ctx.beginPath();ctx.moveTo(x(i/12),y(0));ctx.lineTo(x(i/12),y(1));ctx.stroke();}for(let i=0;i<=10;i++){ctx.globalAlpha=i%2===0?.3:.11;ctx.beginPath();ctx.moveTo(x(0),y(i/10));ctx.lineTo(x(1),y(i/10));ctx.stroke();}ctx.globalAlpha=1;ctx.strokeStyle='#65f4ff';ctx.lineWidth=2;ctx.strokeRect(x(.04),y(.08),w*.92,h*.82);ctx.beginPath();ctx.moveTo(x(.38),y(.08));ctx.lineTo(x(.38),y(.9));ctx.moveTo(x(.62),y(.08));ctx.lineTo(x(.62),y(.9));ctx.moveTo(x(.04),y(.43));ctx.lineTo(x(.38),y(.43));ctx.moveTo(x(.62),y(.43));ctx.lineTo(x(.96),y(.43));ctx.stroke();for(const [id,s] of Object.entries(baseStations)){const sx=x(s.x),sy=y(s.y),color=id==='hydro'?'#70ff9c':id==='hangar'?'#b871ff':'#65f4ff';ctx.strokeStyle=color;ctx.shadowColor=color;ctx.strokeRect(sx-34,sy-18,68,36);ctx.fillStyle=color;ctx.font='700 9px Orbitron';ctx.textAlign='center';ctx.fillText(s.label,sx,sy-27);ctx.beginPath();ctx.arc(sx,sy,5,0,Math.PI*2);ctx.stroke();}for(let i=0;i<bedPositions.length;i++){const p=bedPositions[i],bx=x(p.x),by=y(p.y),bed=hydroBeds[i];ctx.strokeStyle=bed?seedDefs[bed.type].color:'#376b60';ctx.shadowColor=ctx.strokeStyle;ctx.strokeRect(bx-27,by-16,54,32);ctx.beginPath();ctx.moveTo(bx-22,by+10);ctx.lineTo(bx+22,by-10);ctx.moveTo(bx-22,by-10);ctx.lineTo(bx+22,by+10);ctx.stroke();if(bed){const stage=bed.stage||0,def=seedDefs[bed.type];ctx.strokeStyle=def.color;for(let n=-stage;n<=stage;n++){ctx.beginPath();ctx.moveTo(bx+n*7,by+8);ctx.quadraticCurveTo(bx+n*7+(n%2?7:-7),by-stage*7,bx+n*7,by-9-stage*3);ctx.stroke();}ctx.fillStyle=def.color;ctx.font='700 7px Orbitron';ctx.fillText(stage>=3?'READY':`${stage}/3`,bx,by+27);}}ctx.strokeStyle='#b871ff';ctx.shadowColor='#b871ff';ctx.strokeRect(x(.11),y(.55),w*.18,h*.19);ctx.beginPath();ctx.moveTo(x(.2),y(.57));ctx.lineTo(x(.15),y(.7));ctx.lineTo(x(.2),y(.76));ctx.lineTo(x(.25),y(.7));ctx.closePath();ctx.stroke();const px=x(basePlayer.x),py=y(basePlayer.y);ctx.translate(px,py);ctx.rotate(basePlayer.facing+Math.PI/2);ctx.strokeStyle='#f0ffff';ctx.shadowColor='#65f4ff';ctx.lineWidth=1.7;ctx.beginPath();ctx.arc(0,-8,5,0,Math.PI*2);ctx.moveTo(0,-3);ctx.lineTo(0,10);ctx.moveTo(0,2);ctx.lineTo(-8,8);ctx.moveTo(0,2);ctx.lineTo(8,8);ctx.moveTo(0,10);ctx.lineTo(-6,19);ctx.moveTo(0,10);ctx.lineTo(6,19);ctx.stroke();ctx.restore();}
  function drawEnemyFighter(e){ctx.save();ctx.translate(e.x,e.y);const glow=e.flash>0?'#fff':'#ff5d3d';ctx.shadowBlur=16;ctx.shadowColor=glow;ctx.strokeStyle=glow;ctx.fillStyle='#2a0d08';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,18);ctx.lineTo(-14,-8);ctx.lineTo(-5,-4);ctx.lineTo(0,-10);ctx.lineTo(5,-4);ctx.lineTo(14,-8);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle=glow;ctx.shadowBlur=10;ctx.beginPath();ctx.arc(0,4,3,0,Math.PI*2);ctx.fill();ctx.restore();}
  function drawEnemyBolt(b){ctx.save();ctx.translate(b.x,b.y);const ang=Math.atan2(b.vy,b.vx);ctx.rotate(ang);ctx.shadowBlur=14;ctx.shadowColor='#ff5d7a';const g=ctx.createLinearGradient(-14,0,6,0);g.addColorStop(0,'rgba(255,93,122,0)');g.addColorStop(1,'#ffe0e6');ctx.fillStyle=g;ctx.beginPath();ctx.ellipse(-4,0,10,b.r,0,0,Math.PI*2);ctx.fill();ctx.restore();}
  function drawAsteroid(a){const pts=a.shape||[1,1,1,1,1,1,1,1,1],n=pts.length;ctx.save();ctx.translate(a.x,a.y);ctx.rotate(a.rot);ctx.beginPath();for(let i=0;i<n;i++){const ang=i/n*Math.PI*2,rad=a.r*pts[i],px=Math.cos(ang)*rad,py=Math.sin(ang)*rad;if(i===0)ctx.moveTo(px,py);else ctx.lineTo(px,py);}ctx.closePath();const glow=a.gold?'#ffd84d':'#b391ff',rim=a.flash>0?'#fff':glow;ctx.shadowBlur=a.gold?26:15;ctx.shadowColor=glow;const grad=ctx.createRadialGradient(-a.r*.32,-a.r*.32,a.r*.12,0,0,a.r*1.08);grad.addColorStop(0,a.gold?'#7a5518':'#3d3252');grad.addColorStop(.55,a.gold?'#3a2a08':'#241a30');grad.addColorStop(1,'#08060d');ctx.fillStyle=grad;ctx.fill();ctx.lineWidth=a.flash>0?2.6:1.3;ctx.strokeStyle=rim;ctx.stroke();ctx.save();ctx.clip();for(let i=0;i<4;i++){const cx=(pts[i]-.93)*2.3*a.r,cy=(pts[(i+4)%n]-.93)*2.3*a.r,cr=a.r*(.13+(pts[(i+2)%n]-.78)*.45);ctx.beginPath();ctx.arc(cx,cy,cr,0,Math.PI*2);ctx.fillStyle='rgba(0,0,0,.34)';ctx.fill();ctx.beginPath();ctx.arc(cx-cr*.28,cy-cr*.28,cr*.5,0,Math.PI*2);ctx.fillStyle='rgba(255,255,255,.06)';ctx.fill();}ctx.strokeStyle='rgba(255,255,255,.05)';ctx.lineWidth=a.r*.4;ctx.beginPath();ctx.arc(-a.r*.1,-a.r*.15,a.r*.9,Math.PI*1.15,Math.PI*1.75);ctx.stroke();ctx.restore();if(a.gold){ctx.globalAlpha=.5+Math.sin(performance.now()*.006+a.x)*.18;ctx.strokeStyle='#ffe66d';ctx.lineWidth=2.4;ctx.shadowBlur=28;ctx.shadowColor='#ffe66d';ctx.stroke();ctx.globalAlpha=1;}ctx.restore();}
  function draw(dt){if(state.mode==='base'){drawBase();return;}drawAtmosphere(dt);ctx.save();if(state.shake)ctx.translate((Math.random()-.5)*state.shake,(Math.random()-.5)*state.shake);if(state.mode==='playing')drawPlayer();lasers.forEach(drawLaser);asteroids.forEach(drawAsteroid);enemies.forEach(drawEnemyFighter);enemyBolts.forEach(drawEnemyBolt);orbs.forEach(drawOrb);scraps.forEach(drawScrap);powerups.forEach(drawPowerup);fragments.forEach(drawFragment);seedDrops.forEach(drawSeed);if(state.boss)drawDreadnought(state.boss);plasma.forEach(drawPlasma);if(state.bossBeam&&state.boss){const beam=state.bossBeam;ctx.save();if(beam.charge>0){ctx.globalAlpha=.25+.3*Math.sin(performance.now()*.03);ctx.fillStyle='#ff315d';ctx.shadowBlur=35;ctx.shadowColor='#ff315d';ctx.fillRect(beam.x-5,state.boss.y,10,height-state.boss.y);}else{ctx.fillStyle='#fff';ctx.shadowBlur=45;ctx.shadowColor='#ff143f';ctx.fillRect(beam.x-14,state.boss.y,28,height-state.boss.y);ctx.fillStyle='#ff315d';ctx.fillRect(beam.x-28,state.boss.y,56,height-state.boss.y);}ctx.restore();}for(const p of particles){ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;if(p.nova){ctx.strokeStyle=p.color;ctx.lineWidth=5;ctx.shadowBlur=28;ctx.shadowColor=p.color;ctx.beginPath();ctx.arc(p.x,p.y,(1-p.life/p.max)*Math.max(width,height),0,Math.PI*2);ctx.stroke();}else if(p.pixel){ctx.shadowBlur=5;ctx.shadowColor=p.color;ctx.fillRect(Math.round(p.x),Math.round(p.y),p.size*2,p.size);}else ctx.fillRect(p.x,p.y,p.size*2,p.size);}ctx.shadowBlur=0;ctx.globalAlpha=1;if(state.combo>1){const shown=state.combo>=5?5:state.combo>=3?3:2;ctx.save();ctx.translate(width/2,height*.3);ctx.scale(1+state.comboPulse*.35,1+state.comboPulse*.35);ctx.font='800 24px Orbitron, sans-serif';ctx.textAlign='center';ctx.fillStyle='#fff';ctx.shadowBlur=24;ctx.shadowColor='#65f4ff';ctx.fillText(`COMBO x${shown}`,0,0);ctx.restore();}ctx.restore();if(state.flash){ctx.fillStyle=`rgba(255,35,80,${state.flash*1.8})`;ctx.fillRect(0,0,width,height);}}
  function closeStationTerminal(){ui.stationTerminal.classList.remove('active');}
  function terminalCard(title,copy,action='',disabled=false,klass=''){return `<article class="terminal-card ${klass}"><div><h3>${title}</h3><p>${copy}</p></div>${action?`<button ${disabled?'disabled':''} ${action}>${disabled?'LOCKED':'CONFIRM'}</button>`:''}</article>`;}
  function openHydroTerminal(){ui.stationTerminalEyebrow.textContent='BIOSPHERE // AUTOMATION';ui.stationTerminalTitle.textContent='HYDRO-LAB CONTROL';const owned=baseSystems.hydroBot,can=profile.scrap>=150&&baseSystems.gears>=2;ui.stationTerminalBody.innerHTML=`<div class="terminal-ledger"><b>SCRAP ${profile.scrap}</b><b>WIREFRAME GEARS ${baseSystems.gears}</b><b>POWER TIER ${baseSystems.powerTier}</b></div>${terminalCard('AUTOMATED HYDRO-BOT',owned?`ONLINE · ${baseSystems.powerTier>=2?'SOLAR SPEED BOOST ACTIVE':'STANDARD PATROL SPEED'}`:'Automatically waters beds and collects mature yields when you return from a cleared mission.',owned?'':`data-station-action="craft-bot"`,!owned&&!can,owned?'installed':'')}`;ui.stationTerminal.classList.add('active');}
  function openPowerTerminal(){ui.stationTerminalEyebrow.textContent='ENGINEERING // STATION GRID';ui.stationTerminalTitle.textContent='POWER GENERATOR ROOM';const tier=baseSystems.powerTier,cost=tier===1?300:tier===2?750:0;ui.stationTerminalBody.innerHTML=`<div class="terminal-ledger"><b>SCRAP ${profile.scrap}</b><b>ACTIVE TIER ${tier}</b></div>${terminalCard('TIER 1 · REACTOR BUS','Standard cultivation: one mission equals one growth stage.','',false,tier===1?'installed':'')}${terminalCard('TIER 2 · SOLAR ARRAYS','50% faster cultivation and accelerated Hydro-Bot patrol.',tier<2?'data-station-action="power-2"':'',tier<2&&profile.scrap<300,tier===2?'installed':'')}${terminalCard('TIER 3 · FUSION CORE','All hydrated crops mature after every successful mission.',tier<3?'data-station-action="power-3"':'',tier<3&&(tier<2||profile.scrap<750),tier===3?'installed':'')}`;ui.stationTerminal.classList.add('active');}
  function openMerchantTerminal(){ui.stationTerminalEyebrow.textContent='AIRLOCK BAY // VISITOR CHANNEL';ui.stationTerminalTitle.textContent=baseSystems.merchantDocked?'XENO MERCHANT DOCKED':'AIRLOCK VACANT';if(!baseSystems.merchantDocked){ui.stationTerminalBody.innerHTML=terminalCard('NO VESSEL IN BERTH','Merchant signatures are detected occasionally after completed sectors.','','','warning');ui.stationTerminal.classList.add('active');return;}const crops=Object.values(cropInventory).reduce((a,b)=>a+(Number(b)||0),0);ui.stationTerminalBody.innerHTML=`<div class="terminal-ledger"><b>CROPS ${crops}</b><b>SCRAP ${profile.scrap}</b><b>BLUEPRINTS ${blueprintFragments}</b></div>${terminalCard('SELL ONE HARVEST','Exchange any stored crop for 25 Scrap.',crops?'data-station-action="sell-scrap"':'',!crops)}${terminalCard('TRADE HARVEST CACHE','Exchange 3 crops for 1 Blueprint Fragment.',crops>=3?'data-station-action="sell-blueprint"':'',crops<3)}${terminalCard('STAR-FRUIT SEED','Cost: 2 Blueprint Fragments · Harvest grants permanent +1% flight speed.','data-station-action="buy-starfruit"',blueprintFragments<2)}${terminalCard('VOID-PEPPER SEED','Cost: 2 Blueprint Fragments · Harvest loads explosive laser ammunition.','data-station-action="buy-voidpepper"',blueprintFragments<2)}`;ui.stationTerminal.classList.add('active');}
  function openCommandTerminal(){ui.stationTerminalEyebrow.textContent='COMMAND DECK // EXPANSION GRID';ui.stationTerminalTitle.textContent='MOTHER BASE UPGRADE TREE';const planet=planetFor(unlockedLevel);const resourceLine=Object.entries(resourceInventory).map(([k,v])=>`${planetDefs.find(p=>p.resource===k).code} ${v}`).join(' · ')||'NONE COLLECTED';ui.stationTerminalBody.innerHTML=`<div class="terminal-ledger"><b>SCRAP ${profile.scrap}</b><b>NEXT SECTOR ${unlockedLevel}</b></div>${terminalCard(`DEPART FOR ${planet.name}`,`Engage ${planet.name} · ${unlockedLevel} boss signature${unlockedLevel===1?'':'s'} · Harvest ${planet.resourceName}.`,'data-station-action="launch"')}<div class="terminal-section-label">PLAGUE RESEARCH // EARTH STATION</div>${terminalCard('CURE RESEARCH PROGRESS',`${Math.floor(cureProgress)}% complete · Earth population ${Math.round(earthPopulation).toLocaleString('en-US')}.`,'',true)}${baseSystems.researchLab?terminalCard('DEPOSIT COLLECTED RESOURCES',`Cargo hold: ${resourceLine}. Converts all resources into cure progress.`,'data-station-action="deposit-resources"',totalResources()<=0):terminalCard('RESEARCH LAB',`Unlocks resource-to-cure conversion at this terminal.`,'data-station-action="base-research"',profile.scrap<900)}${terminalCard('DEEP SPACE SENSORS','+50% resource yield from every Dreadnought kill.',baseSystems.deepSensors?'':'data-station-action="base-sensors"',!baseSystems.deepSensors&&profile.scrap<550,baseSystems.deepSensors?'installed':'')}<div class="terminal-section-label">BASE EXPANSIONS</div>${terminalCard('AUTOMATED DEFENSE TURRETS','Station-wall sentries and passive +12 shield repair during flight.',baseSystems.defenseTurrets?'':'data-station-action="base-defense"',!baseSystems.defenseTurrets&&profile.scrap<500,baseSystems.defenseTurrets?'installed':'')}${terminalCard('ADVANCED HYDRO RACKS','Adds four persistent planting beds to the Biosphere.',baseSystems.advancedHydro?'':'data-station-action="base-hydro"',!baseSystems.advancedHydro&&profile.scrap<650,baseSystems.advancedHydro?'installed':'')}${terminalCard('SEED TRANSMUTER','Converts any 3 basic seeds into one chosen exotic seed.',baseSystems.seedTransmuter?'':'data-station-action="base-transmuter"',!baseSystems.seedTransmuter&&profile.scrap<800,baseSystems.seedTransmuter?'installed':'')}${baseSystems.seedTransmuter?terminalCard('TRANSMUTE STAR-FRUIT','Consume 3 basic seeds.','data-station-action="transmute-starfruit"',basicSeedCount()<3)+terminalCard('TRANSMUTE VOID-PEPPER','Consume 3 basic seeds.','data-station-action="transmute-voidpepper"',basicSeedCount()<3):''}`;ui.stationTerminal.classList.add('active');}
  function openSuitTerminal(){const options=[['cyan','#65f4ff',1],['pink','#ff6de5',3],['gold','#ffe66d',6]];ui.stationTerminalEyebrow.textContent='CREW QUARTERS // PILOT LOCKER';ui.stationTerminalTitle.textContent='SUIT SPECTRUM';ui.stationTerminalBody.innerHTML=options.map(([id,color,level])=>terminalCard(`${id.toUpperCase()} WIREFRAME SUIT`,`Campaign unlock: Sector ${level} · ${unlockedLevel>=level?'AVAILABLE':'LOCKED'}`,unlockedLevel>=level?`data-station-action="suit-${id}"`:'',unlockedLevel<level,baseSystems.suitTint===id?'installed':'')).join('');ui.stationTerminal.classList.add('active');}
  function basicSeedCount(){return ['lettuce','carrot','potato'].reduce((n,k)=>n+(seedInventory[k]||0),0);}
  function consumeBasicSeeds(count=3){for(const k of ['lettuce','carrot','potato']){const n=Math.min(count,seedInventory[k]||0);seedInventory[k]-=n;count-=n;if(!count)return true;}return false;}
  function harvestBed(index,automated=false){const bed=hydroBeds[index];if(!bed||bed.stage<3)return false;cropInventory[bed.type]=(cropInventory[bed.type]||0)+1;if(bed.type==='starfruit')baseSystems.permanentSpeed=Math.min(20,(baseSystems.permanentSpeed||0)+1);else runBuffs[seedDefs[bed.type].buff]=(runBuffs[seedDefs[bed.type].buff]||0)+1;hydroBeds[index]=null;if(automated)ui.basePrompt.textContent=`HYDRO-BOT RETURN REPORT · ${seedDefs[bed.type].name} STORED`;return true;}
  function runHydroAutomation(){if(!baseSystems.hydroBot||!pendingAutomation)return;let harvested=0;hydroBeds.forEach((b,i)=>{if(b?.stage>=3){harvested+=harvestBed(i,true)?1:0;}else if(b)b.hydrated=true;});pendingAutomation=false;saveFarm();if(harvested)pickupChime(true);}
  function takeCrop(count){for(const key of Object.keys(cropInventory)){const n=Math.min(count,cropInventory[key]||0);cropInventory[key]-=n;count-=n;if(!count)return true;}return false;}
  const stationWorld={width:2670,height:1540,rooms:[{id:'hangar',name:'HANGAR BAY',x:70,y:90,w:720,h:530,color:'#b871ff'},{id:'command',name:'COMMAND DECK',x:1090,y:80,w:690,h:470,color:'#65f4ff'},{id:'quarters',name:'CREW QUARTERS',x:80,y:970,w:710,h:470,color:'#4b9dff'},{id:'hydro',name:'BIOSPHERE / HYDRO-LAB',x:1080,y:900,w:710,h:550,color:'#70ff9c'},{id:'power',name:'POWER GENERATOR ROOM',x:1900,y:80,w:680,h:520,color:'#ffe66d'},{id:'airlock',name:'AIRLOCK BAY',x:1900,y:920,w:680,h:520,color:'#ff6de5'}],corridors:[{x:780,y:250,w:330,h:190},{x:845,y:250,w:200,h:850},{x:720,y:770,w:1260,h:210},{x:780,y:1090,w:320,h:190},{x:1765,y:270,w:170,h:170},{x:1765,y:1090,w:170,h:190}],terminals:{hangar:{x:720,y:360,label:'ASSEMBLY CONSOLE'},command:{x:1190,y:350,label:'MISSION CONTROL'},hydro:{x:1165,y:1020,label:'HYDRO CONTROL'},quarters:{x:700,y:1160,label:'CREW ARCHIVE'},power:{x:2020,y:350,label:'GENERATOR TERMINAL'},airlock:{x:2030,y:1100,label:'TRADE TERMINAL'}},beds:[{x:1240,y:1045},{x:1410,y:1045},{x:1580,y:1045},{x:1700,y:1045},{x:1240,y:1265},{x:1410,y:1265},{x:1580,y:1265},{x:1700,y:1265}],camera:{x:0,y:0}};
  const stationDust=Array.from({length:80},()=>({x:Math.random()*stationWorld.width,y:Math.random()*stationWorld.height,r:.6+Math.random()*1.8,phase:Math.random()*6.28,speed:.15+Math.random()*.3,drift:(Math.random()-.5)*10}));
  function drawStationDust(){const time=performance.now()*.0006;ctx.save();for(const d of stationDust){const dy=(d.y+time*30*d.speed)%stationWorld.height,dx=d.x+Math.sin(time*.6+d.phase)*d.drift;const alpha=.12+.1*Math.sin(time*3+d.phase);ctx.globalAlpha=Math.max(0,alpha);ctx.fillStyle='#8fd8ff';ctx.beginPath();ctx.arc(dx,dy,d.r,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;ctx.restore();}
  function pointInStation(x,y){return stationWorld.rooms.some(r=>x>r.x+6&&x<r.x+r.w-6&&y>r.y+6&&y<r.y+r.h-6)||stationWorld.corridors.some(r=>x>r.x+2&&x<r.x+r.w-2&&y>r.y+2&&y<r.y+r.h-2);}
