  function nearestBaseTarget(){const targets=[...Object.entries(stationWorld.terminals).map(([kind,t])=>({kind,...t})),...stationWorld.beds.slice(0,baseSystems.advancedHydro?8:4).map((b,index)=>({kind:'bed',index,...b}))];let best=null,dist=Infinity;for(const t of targets){const d=Math.hypot(basePlayer.x-t.x,basePlayer.y-t.y);if(d<dist){dist=d;best=t;}}return dist<92?best:null;}
